#[unsafe(export_name = "destack.thread.local.create")]
pub unsafe extern "C" fn destack_thread_local_create(
    out: *mut resource::ThreadLocalKey,
) -> RuntimeStatus {
    native_call(|context| {
        if out.is_null() {
            return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
        }
        let _ = &out;

        {
            let (world, _binding_hook_guard) =
                context.on_before_binding_resolve_world(THREAD_LOCAL_CREATE)?;
            match world {
                RuntimeWorld::Host => unsafe {
                    platform_native::destack_thread_local_create(context, out)
                },
                RuntimeWorld::Simulation => unsafe {
                    platform_simulation_native::destack_thread_local_create(context, out)
                },
            }
        }
    })
}

